mod snapshot_integrity;

use snapshot_integrity::{compute_integrity, dual_hash, verify_integrity, verify_with_chain_hash};

fn main() {
    let original = dual_hash(0, 0);
    let colliding = dual_hash(0, 1_u64 << 63);
    assert_eq!(original, 0);
    assert_eq!(colliding, original);
    let mut integrity = compute_integrity(0, 0, 17);
    assert!(verify_integrity(&integrity));
    integrity.meta_hash = 1_u64 << 63;
    let tampered_metadata_accepted = verify_integrity(&integrity);
    let chain_check_also_accepts = verify_with_chain_hash(&integrity, 17);
    assert!(tampered_metadata_accepted);
    assert!(chain_check_also_accepts);
    println!(
        "{{\"original_hash\":{original},\"colliding_hash\":{colliding},\"tampered_metadata\":{},\"tampered_metadata_accepted\":{tampered_metadata_accepted},\"chain_check_also_accepts\":{chain_check_also_accepts}}}",
        integrity.meta_hash,
    );
}
